"""No network or real credentials; TC3 vector generated by official Tencent Python SDK."""
import json
import unittest
from unittest.mock import patch

from provider_catalog import checked_config, TransportError
from yuanbao_auth import build_request, checked_response


STANDARD={'provider':'yuanbao','auth_mode':'standard','secret_id':'AKIDfixture','secret_key':'fixture-secret-key'}


class YuanbaoSigningTests(unittest.TestCase):
    def test_fixed_fake_credential_signature_matches_official_sdk_oracle(self):
        # SDK abstract_client.py _get_tc3_signature + sign.py Sign.sign_tc3;
        # generated offline with these fake values, never the redacted documentation key.
        url,raw,headers=build_request(STANDARD,{'Query':'fixture-query','Cnt':10,'Mode':0},1551113065)
        self.assertEqual(url,'https://wsa.tencentcloudapi.com/')
        self.assertEqual(raw,b'{"Query": "fixture-query", "Cnt": 10, "Mode": 0}')
        self.assertEqual(headers['Authorization'],'TC3-HMAC-SHA256 Credential=AKIDfixture/2019-02-25/wsa/tc3_request, SignedHeaders=content-type;host, Signature=f7a0d1fe37c56756d05ff2cc8b3f48a2de38f24c44075e085302528eec6a1606')
        self.assertEqual(headers['Content-Type'],'application/json')
        self.assertEqual(headers['X-TC-Action'],'SearchPro')
        self.assertEqual(headers['X-TC-Version'],'2025-05-08')
        self.assertEqual(headers['X-TC-Timestamp'],'1551113065')
        self.assertNotIn('X-TC-Region',headers)
        self.assertNotIn('fixture-secret-key',json.dumps(headers))

    def test_query_bytes_are_preserved_and_timestamp_uses_utc(self):
        with patch('yuanbao_auth.time.time',return_value=1551113065):
            _,raw,headers=build_request(STANDARD,{'Query':'天津考研'})
        self.assertEqual(json.loads(raw),{'Query':'天津考研'})
        self.assertIn('/2019-02-25/wsa/tc3_request',headers['Authorization'])
        other=build_request(STANDARD,{'Query':'天津考研2'},1551113065)
        self.assertNotEqual(headers['Authorization'],other[2]['Authorization'])

    def test_legacy_api_key_uses_bearer_and_cannot_be_sent_to_standard_host(self):
        config={'provider':'yuanbao','api_key':'fixture-api-key'}
        url,raw,headers=build_request(config,{'Query':'fixture'})
        self.assertEqual(url,'https://api.wsa.cloud.tencent.com/SearchPro')
        self.assertEqual(headers['Authorization'],'Bearer fixture-api-key')
        self.assertEqual(json.loads(raw),{'Query':'fixture'})
        self.assertFalse(any(k.startswith('X-TC-') for k in headers))
        for base in ['https://wsa.tencentcloudapi.com/','https://api.wsa.cloud.tencent.com/other','https://evil.example/SearchPro']:
            with self.subTest(base=base),self.assertRaises(TransportError):build_request({**config,'base_url':base},{'Query':'fixture'})

    def test_standard_rejects_wrong_endpoint_credentials_and_mixed_modes(self):
        for extra in [{'base_url':'https://api.wsa.cloud.tencent.com/SearchPro'},
                      {'base_url':'https://wsa.tencentcloudapi.com/other'},
                      {'base_url':'https://user:pass@wsa.tencentcloudapi.com/'},
                      {'secret_id':''},{'secret_key':''},{'secret_id':'AKID\r\nInjected'},
                      {'secret_key':42},{'secret_key':'bad key'},{'api_key':'wrong-mode'},
                      {'api_key':[]},{'model':[]},{'model':'wrong-model'},
                      {'auth_mode':'unknown'},{'auth_mode':[]}]:
            with self.subTest(extra=extra),self.assertRaises(TransportError):checked_config({**STANDARD,**extra})
        with self.assertRaises(TransportError):checked_config({'provider':'yuanbao','api_key':'k','secret_id':'unexpected'})
        with self.assertRaises(TransportError):checked_config({'provider':'deepseek','api_key':'k','auth_mode':'standard','secret_id':'AKIDfixture','secret_key':'fixture-key'})

    def test_bad_body_and_timestamp_are_rejected_without_raw_secrets(self):
        for body in [None,[],{'value':float('inf')},{'Query':'x'*(1024*1024+1)}]:
            with self.subTest(type=type(body)),self.assertRaises(TransportError) as caught:build_request(STANDARD,body,1551113065)
            self.assertNotIn(STANDARD['secret_key'],str(caught.exception))
        for stamp in [True,-1,'1551113065',10**30]:
            with self.subTest(stamp=stamp),self.assertRaises(TransportError):build_request(STANDARD,{'Query':'fixture'},stamp)


class YuanbaoResponseTests(unittest.TestCase):
    def test_known_service_errors_are_classified_without_upstream_message(self):
        cases={'AuthFailure.SignatureFailure':'provider_auth_failed','AuthFailure.SecretIdNotFound':'provider_auth_failed',
               'AuthFailure.SignatureExpire':'signature_expired','UnauthorizedOperation':'provider_permission_denied',
               'ResourceUnavailable':'search_unavailable','ResourceNotFound':'search_not_enabled',
               'RequestLimitExceeded':'provider_rate_limited','InternalError':'provider_request_failed'}
        for remote,expected in cases.items():
            with self.subTest(remote=remote),self.assertRaises(TransportError) as caught:
                checked_response({'Response':{'Error':{'Code':remote,'Message':'LEAKED-private-key-and-id'}}})
            self.assertEqual(caught.exception.code,expected)
            self.assertNotIn('LEAKED',str(caught.exception))

    def test_valid_wrapped_and_unwrapped_pages_and_invalid_shape(self):
        body={'Pages':[],'RequestId':'fixture-request'}
        self.assertEqual(checked_response({'Response':body}),body)
        self.assertEqual(checked_response(body),body)
        empty={'RequestId':'fixture-request','Query':'公开查询','Version':'standard'}
        self.assertEqual(checked_response({'Response':empty}),{**empty,'Pages':[]})
        self.assertEqual(checked_response(empty),{**empty,'Pages':[]})
        for value in [[],{}, {'Response':[]},{'Response':{'Pages':'bad'}},
                      {'Response':{'RequestId':'x'}},{'Response':{'Version':'standard'}},
                      {'Response':{'Error':'bad'}}]:
            with self.subTest(value=value),self.assertRaises(TransportError):checked_response(value)


if __name__=='__main__':unittest.main()
